import {mkdirSync,writeFileSync,readFileSync,chmodSync} from 'node:fs';
import {resolve} from 'node:path';
import assert from 'node:assert/strict';
import {loadE2EEnvironment} from '../../e2e/environment.ts';
const root=resolve('/Users/dingshinn/.codex/worktrees/step-07-review-round9/rpg-maker-maker/.local/step07-review/config-controls-ports');mkdirSync(root);
const path=resolve(root,'.env');writeFileSync(path,'API_PORT=4395\nWEB_PORT=5295\n',{mode:0,flag:'wx'});
for(const key of ['API_HOST','API_PORT','WEB_PORT','NODE_ENV'])delete process.env[key];process.env.DATABASE_URL='[REDACTED_DSN]';
let errno='';try{readFileSync(path)}catch(e:any){errno=e.code}assert.equal(errno,'EACCES');
const config=loadE2EEnvironment(path);assert.deepEqual([config.API_PORT,config.WEB_PORT],[4310,5173]);
console.log(JSON.stringify({source:'50fd6d84197b8c6d222f139a142ab24c918db0db',result:'COUNTEREXAMPLE_CAPTURED_NOT_CANDIDATE_PASS',actualFsError:errno,existingFilePorts:[4395,5295],explicitConfiguration:'DATABASE_URL only',actualSilentlyDefaultedPorts:[config.API_PORT,config.WEB_PORT],expected:'reject unreadable existing file',DBConnected:false}));
chmodSync(path,0o600);
